head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");


//상장형 수익증권 담당종목 지정 
scwin.vScrenID = 'ULDSTF34200.xml';
scwin.todat = "";
scwin.grd_HandOverIsuList_nm = "";
scwin.grd_TakeOverIsuList_nm = "";
scwin.grd_byCorpList_nm = "";
scwin.grd_chgByCorpList_nm = "";
scwin.grd_allByCorpList_nm = "";
scwin.gubun = 0; //어느화면에서 수정했는지 체크.

scwin.tmpIdx1 = "";
scwin.tmpIdx2 = "";
scwin.gBizTpCd = "";
scwin.gLdMktTpCd = "";
scwin.gUpDepCd = "";
scwin.gETFYn = "N";
scwin.gPFYn = "N";
scwin.all_list_count = 0; // 전체 담당지정 법인 목록	
scwin.filter_cnt = 0; //filter된 법인목록
scwin.gSecugrpId = "";
scwin.isInit = true;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //초기화인 경우 alert 표시 안되도록.

scwin.getQuery = function(srcUrl, id) {
    if (srcUrl.indexOf("?") < 0) return "";
    var queryStr = srcUrl.split("?")[1];
    var val = queryStr.split("&");
    for (var i = 0; i < val.length; i++) {
        var tmp = val[i].split("=");
        if (id == tmp[0]) {
            return tmp[1];
        }
    }
    return "";
};
scwin.fn_getParam = function() {
    var parentWin = $c.frame.path("../");
    //alert("[frame.srcUrl]"+frame.srcUrl);
    scwin.gBizTpCd = $c.stf.getQuery(frame.srcUrl, "src");
    //alert("[gBizTpCd]"+gBizTpCd);

    if (scwin.gBizTpCd == 'STK') {
        scwin.gLdMktTpCd = "1";
        scwin.gUpDepCd = "2600";
    } else if (scwin.gBizTpCd == 'KSQ') {
        scwin.gLdMktTpCd = "2";
        scwin.gUpDepCd = "3400";
    } else if (scwin.gBizTpCd == 'KNX') {
        scwin.gLdMktTpCd = "6";
        scwin.gUpDepCd = "3B00";
    } else if (scwin.gBizTpCd == 'ETF') {
        scwin.gLdMktTpCd = "1";
        scwin.gUpDepCd = "2B00";
        scwin.gETFYn = "Y";
        scwin.gSecugrpId = 'EF';
    } else if (scwin.gBizTpCd == 'PF') {
        scwin.gLdMktTpCd = "1";
        scwin.gUpDepCd = "2B00";
        scwin.gPFYn = "Y";
        scwin.gSecugrpId = 'PF';
    } else {
        $c.win.alert('파라미터값 확인 오류');
    }
};
scwin.alert_error3 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j).substring(0, 220));
        }
    }
};
scwin.setGrid = function() {
    if (scwin.gLdMktTpCd == "2" || scwin.gLdMktTpCd == '6') {
        $c.cm.setColumnProp(grd_HandOverIsuList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_TakeOverIsuList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_nonByCorpList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_byCorpList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_allByCorpList, "SECT_TP_NM", "Show", true);
        $c.cm.setColumnProp(grd_chgByCorpList, "SECT_TP_NM", "Show", true);
    } else {
        $c.cm.setColumnProp(grd_HandOverIsuList, "SECT_TP_NM", "Show", false);
        $c.cm.setColumnProp(grd_TakeOverIsuList, "SECT_TP_NM", "Show", false);
        $c.cm.setColumnProp(grd_nonByCorpList, "SECT_TP_NM", "Show", false);
        $c.cm.setColumnProp(grd_byCorpList, "SECT_TP_NM", "Show", false);
        $c.cm.setColumnProp(grd_allByCorpList, "SECT_TP_NM", "Show", false);
        $c.cm.setColumnProp(grd_chgByCorpList, "SECT_TP_NM", "Show", false);
    }
    if (scwin.gLdMktTpCd == "2") {
        $c.cm.setColumnProp(grd_HandOverIsuList, "IDX_IND_NM", "Show", true);
        $c.cm.setColumnProp(grd_TakeOverIsuList, "IDX_IND_NM", "Show", true);
        $c.cm.setColumnProp(grd_nonByCorpList, "IDX_IND_NM", "Show", true);
        $c.cm.setColumnProp(grd_byCorpList, "IDX_IND_NM", "Show", true);
        $c.cm.setColumnProp(grd_allByCorpList, "IDX_IND_NM", "Show", true);
        $c.cm.setColumnProp(grd_chgByCorpList, "IDX_IND_NM", "Show", true);
    } else {
        $c.cm.setColumnProp(grd_HandOverIsuList, "IDX_IND_NM", "Show", false);
        $c.cm.setColumnProp(grd_TakeOverIsuList, "IDX_IND_NM", "Show", false);
        $c.cm.setColumnProp(grd_nonByCorpList, "IDX_IND_NM", "Show", false);
        $c.cm.setColumnProp(grd_byCorpList, "IDX_IND_NM", "Show", false);
        $c.cm.setColumnProp(grd_allByCorpList, "IDX_IND_NM", "Show", false);
        $c.cm.setColumnProp(grd_chgByCorpList, "IDX_IND_NM", "Show", false);
    }
    if (scwin.gLdMktTpCd == "2") {

    } else {
        if (scwin.gLdMktTpCd == "6") {
            $c.cm.setColumnProp(grd_HandOverIsuList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_HandOverIsuList, "IND_ABBRV", "Width") + 100);
            $c.cm.setColumnProp(grd_TakeOverIsuList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_TakeOverIsuList, "IND_ABBRV", "Width") + 100);
            $c.cm.setColumnProp(grd_nonByCorpList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_nonByCorpList, "IND_ABBRV", "Width") + 50);
            $c.cm.setColumnProp(grd_byCorpList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_byCorpList, "IND_ABBRV", "Width") + 100);
            $c.cm.setColumnProp(grd_allByCorpList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_allByCorpList, "IND_ABBRV", "Width") + 50);
            $c.cm.setColumnProp(grd_chgByCorpList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_chgByCorpList, "IND_ABBRV", "Width") + 100);
        } else {
            $c.cm.setColumnProp(grd_HandOverIsuList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_HandOverIsuList, "IND_ABBRV", "Width") + 150);
            $c.cm.setColumnProp(grd_TakeOverIsuList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_TakeOverIsuList, "IND_ABBRV", "Width") + 150);
            $c.cm.setColumnProp(grd_nonByCorpList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_nonByCorpList, "IND_ABBRV", "Width") + 100);
            $c.cm.setColumnProp(grd_byCorpList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_byCorpList, "IND_ABBRV", "Width") + 150);
            $c.cm.setColumnProp(grd_allByCorpList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_allByCorpList, "IND_ABBRV", "Width") + 120);
            $c.cm.setColumnProp(grd_chgByCorpList, "IND_ABBRV", "Width", $c.cm.getColumnProp(grd_chgByCorpList, "IND_ABBRV", "Width") + 140);
        }

        //ETF와 PF와 동일 20250509
        if (scwin.gETFYn == "Y" || scwin.gPFYn == "Y") {
            $c.cm.setColumnProp(grd_HandOverIsuList, "IND_ABBRV", "Show", false);
            $c.cm.setColumnProp(grd_TakeOverIsuList, "IND_ABBRV", "Show", false);
            $c.cm.setColumnProp(grd_nonByCorpList, "IND_ABBRV", "Show", false);
            $c.cm.setColumnProp(grd_byCorpList, "IND_ABBRV", "Show", false);
            $c.cm.setColumnProp(grd_allByCorpList, "IND_ABBRV", "Show", false);
            $c.cm.setColumnProp(grd_chgByCorpList, "IND_ABBRV", "Show", false);
            $c.cm.setColumnProp(grd_HandOverIsuList, "COM_ABBRV", "Width", $c.cm.getColumnProp(grd_HandOverIsuList, "COM_ABBRV", "Width") + 150);
            $c.cm.setColumnProp(grd_TakeOverIsuList, "COM_ABBRV", "Width", $c.cm.getColumnProp(grd_TakeOverIsuList, "COM_ABBRV", "Width") + 150);
            $c.cm.setColumnProp(grd_nonByCorpList, "COM_ABBRV", "Width", $c.cm.getColumnProp(grd_nonByCorpList, "COM_ABBRV", "Width") + 100);
            $c.cm.setColumnProp(grd_byCorpList, "COM_ABBRV", "Width", $c.cm.getColumnProp(grd_byCorpList, "COM_ABBRV", "Width") + 150);
            $c.cm.setColumnProp(grd_allByCorpList, "COM_ABBRV", "Width", $c.cm.getColumnProp(grd_allByCorpList, "COM_ABBRV", "Width") + 120);
            $c.cm.setColumnProp(grd_chgByCorpList, "COM_ABBRV", "Width", $c.cm.getColumnProp(grd_chgByCorpList, "COM_ABBRV", "Width") + 140);
        }
    }
};
scwin.fn_todat = function() {
    //alert('[InfoMenuID]'+InfoMenuID());
    scwin.todat = $c.ut.cGetToday("yyyymmdd");
};


//담당자 목록
scwin.fn_list_usr_sync = function() {
    var url = "/PFInfo.do?method=searchDepUsr&inputMessageId=tbld_dep_usr&outputMessageId=tbld_dep_usr&UP_DEP_CD=" + scwin.gUpDepCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //담당자간 인수인계 - 인계인 선택
    dts_HandOverEmpList.DataID = encodeURI(url);
    dts_HandOverEmpList.reset();

    //담당자간 인수인계 - 인수인 선택		
    dts_TakeOverEmpList.DataID = encodeURI(url);
    dts_TakeOverEmpList.reset();

    //미지정회사 담당자지정 - 담당자 선택		
    dts_byCorpEmpList.DataID = encodeURI(url);
    dts_byCorpEmpList.reset();

    //담당자변경 - 담당자 선택			
    dts_chgEmpList.DataID = encodeURI(url);
    dts_chgEmpList.reset();
};



//담당자인수인계 - 인계인의 종목
scwin.fn_list_bycorpusr1 = function() {
    var url = "/PFInfo.do?method=searchCorpIsu&inputMessageId=search_corp_isu&outputMessageId=search_corp_isu&DEP_CD=" + scwin.gUpDepCd + "&SECUGRP_ID=" + scwin.gSecugrpId + "&INTEG_USR_ID=" + dts_HandOverEmpList.getCellData(cmb_HandOverEmpList.getSelectedIndex() + 1, "USR_ID") + "&GUBN=2";
    dts_HandOverIsuList.DataID = encodeURI(url);
    dts_HandOverIsuList.reset();
};


//담당자인수인계 - 인수인의 종목
scwin.fn_list_bycorpusr2 = function() {
    var url = "/PFInfo.do?method=searchCorpIsu&inputMessageId=search_corp_isu&outputMessageId=search_corp_isu&DEP_CD=" + scwin.gUpDepCd + "&SECUGRP_ID=" + scwin.gSecugrpId + "&INTEG_USR_ID=" + dts_TakeOverEmpList.getCellData(cmb_TakeOverEmpList.getSelectedIndex() + 1, "USR_ID") + "&GUBN=2";
    dts_TakeOverIsuList.DataID = encodeURI(url);
