//담당자 변경 - 선택한 담당자 목록
scwin.fn_list_bycorpusr4 = function() {
    var url = "/PFInfo.do?method=searchCorpIsu&inputMessageId=search_corp_isu&outputMessageId=search_corp_isu&DEP_CD=" + scwin.gUpDepCd + "&SECUGRP_ID=" + scwin.gSecugrpId + "&INTEG_USR_ID=" + dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "USR_ID") + "&GUBN=2";
    dts_chgByCorpList.DataID = encodeURI(url);
    dts_chgByCorpList.reset();
};


//담당자 변경 - 팀별 종목전체
scwin.fn_list_bycorpusr5 = function() {
    var url = "/PFInfo.do?method=searchCorpIsu&inputMessageId=search_corp_isu&outputMessageId=search_corp_isu&DEP_CD=" + scwin.gUpDepCd + "&SECUGRP_ID=" + scwin.gSecugrpId + "&GUBN=1";
    dts_allByCorpList.DataID = encodeURI(url);
    dts_allByCorpList.reset();
};


//미지정종목 검색 리스트
scwin.fn_list_nodesign = function() {
    var gGubun = scwin.gLdMktTpCd; //gubn 1:유가, 2:코스닥, 6 : 코넥스, 0 : ETF
    if (scwin.gETFYn == 'Y' || scwin.gPFYn == 'Y') {
        gGubun = '0';
    }
    var url = "/PFInfo.do?method=searchBycorpnoDesign&inputMessageId=bycorpnodesign&outputMessageId=bycorpnodesign&GUBN=" + gGubun + "&SECUGRP_ID=" + scwin.gSecugrpId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_nonByCorpList.DataID = encodeURI(url);
    dts_nonByCorpList.reset();
};


//담당자지정내역 - Detail 종목별 담당자 history	- 회사의 history
scwin.fn_list_history3 = function(sIsurCd) {
    var url2 = "/PFInfo.do?method=searchIsurcdHistory&inputMessageId=isurcdhistory&outputMessageId=isurcdhistory&ISUR_CD=" + sIsurCd;
    dts_searchByCorpDetail.DataID = encodeURI(url2);
    dts_searchByCorpDetail.reset(); //종목별

};


//담당자지정내역 - 종목목록
scwin.fn_list_kospi_all = function() {
    var url = "/PFInfo.do?method=searchIsurCdWithChrg&inputMessageId=comwithchrg&outputMessageId=comwithchrg&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.gLdMktTpCd + "&GUBN=" + scwin.gSecugrpId;
    dts_searchByCorpList.DataID = encodeURI(url);
    dts_searchByCorpList.reset();
};


/*----------------------------------------------------------------------------
	** 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. 
-------------------------------------------------------------------------------*/
scwin.fn_cntDatasetRowCheck = function(sval) {
    cCnt = 0;
    for (i = 1; i <= sval.getTotalRow(); i++) {
        //alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") == 1) {
            cCnt++;
        }
    }
    if (cCnt == 0) {
        return false;
    } else {
        return true;
    }
};



/*----------------------------------------------------------------------------
	** 일괄 인수인계 처리 
-------------------------------------------------------------------------------*/
scwin.fn_All_HandOver = function() {
    //일괄처리 
    scwin.gubun = 1;
    var rowcnt = dts_HandOverIsuList.getTotalRow();
    if (rowcnt == 0) {
        $c.win.alert("처리할 사항이 없습니다.");
        return;
    }
    var msg = $c.stf.getMessageParam("MSG-A006", "일괄인계");
    var res = window.confirm(msg);
    if (res) {
        if (scwin.chkDupDisign(dts_HandOverIsuList)) {
            $c.win.alert("한 회사에 대해 같은날 두번 이상 담당자 변경을 할 수 없습니다.\n관리자에게 문의 하십시오.");
            return;
        }
        for (var i = 1; i <= dts_HandOverIsuList.getTotalRow(); i++) {
            dts_Save.insertRow();
            dts_Save.setCellData(i, "ISUR_CD", dts_HandOverIsuList.getCellData(i, "ISUR_CD"));
            dts_Save.setCellData(i, "PRE_USR_ID", dts_HandOverEmpList.getCellData(cmb_HandOverEmpList.getSelectedIndex() + 1, "USR_ID"));
            dts_Save.setCellData(i, "PRE_DEP_CD", dts_HandOverEmpList.getCellData(cmb_HandOverEmpList.getSelectedIndex() + 1, "DEP_CD"));
            dts_Save.setCellData(i, "AF_USR_ID", dts_TakeOverEmpList.getCellData(cmb_TakeOverEmpList.getSelectedIndex() + 1, "USR_ID"));
            dts_Save.setCellData(i, "AF_DEP_CD", dts_TakeOverEmpList.getCellData(cmb_TakeOverEmpList.getSelectedIndex() + 1, "DEP_CD"));
        }
        trs_Save.Action = "/PFInfo.do?method=saveCorpIsu&inputMessageId=search_corp_isu" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
        trs_Save.Post();
    }
};




//한날에 두번 담당자 변경을 하느냐.
scwin.chkDupDisign = function(obj) {
    var isDup = false;
    for (var i = 1; i <= obj.getTotalRow(); i++) {
        if (obj.getCellData(i, "CHK_FLAG") == 1) {
            if (obj.getCellData(i, "ASSGN_STRT_DD") == scwin.todat) {
                $c.win.alert("'" + obj.getCellData(i, "COM_ABBRV") + "' 는(은)  금일 이미 변경 하셨습니다.");
                isDup = true;
            }
        }
    }
    return isDup;
};


/*----------------------------------------------------------------------------
	** 선택 인수인계 처리 
-------------------------------------------------------------------------------*/
scwin.fn_Select_TakeOver = function() {
    //선택처리
    scwin.gubun = 1;
    var tmpInt = 1;
    if (!scwin.fn_cntDatasetRowCheck(dts_HandOverIsuList)) {
        $c.win.alert("적용할 체크사항이 없습니다.");
    } else {
        var msg = $c.stf.getMessageParam("MSG-A006", "선택인계");
        var res = window.confirm(msg);
        if (res) {
            if (scwin.chkDupDisign(dts_HandOverIsuList)) {
                $c.win.alert("한 회사에 대해 같은날 두번 이상 담당자 변경을 할 수 없습니다.\n관리자에게 문의 하십시오.");
                return;
            }
            for (var i = 1; i <= dts_HandOverIsuList.getTotalRow(); i++) {
                if (dts_HandOverIsuList.getCellData(i, "CHK_FLAG") == 1) {
                    dts_Save.insertRow();
                    dts_Save.setCellData(tmpInt, "ISUR_CD", dts_HandOverIsuList.getCellData(i, "ISUR_CD"));
                    dts_Save.setCellData(tmpInt, "PRE_USR_ID", dts_HandOverEmpList.getCellData(cmb_HandOverEmpList.getSelectedIndex() + 1, "USR_ID"));
                    dts_Save.setCellData(tmpInt, "PRE_DEP_CD", dts_HandOverEmpList.getCellData(cmb_HandOverEmpList.getSelectedIndex() + 1, "DEP_CD"));
                    dts_Save.setCellData(tmpInt, "AF_USR_ID", dts_TakeOverEmpList.getCellData(cmb_TakeOverEmpList.getSelectedIndex() + 1, "USR_ID"));
                    dts_Save.setCellData(tmpInt, "AF_DEP_CD", dts_TakeOverEmpList.getCellData(cmb_TakeOverEmpList.getSelectedIndex() + 1, "DEP_CD"));
                    tmpInt++;
                }
            }
            trs_Save.Action = "/PFInfo.do?method=saveCorpIsu&inputMessageId=search_corp_isu" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
            trs_Save.Post();
        }
    }
};
scwin.fn_stock_add = function() {
    //미지정 종목 추가
    if (!scwin.fn_cntDatasetRowCheck(dts_nonByCorpList)) {
        $c.win.alert("추가할 종목의  체크사항이 없습니다.");
    } else {
        scwin.isInit = false;
        scwin.canDesign();
    }
};
scwin.canDesign = function() {
    var isur_cds = scwin.getCheckedIsurCd();
    var url = "/PFInfo.do?method=getAlreadDesignedInfo&outputMessageId=undesignInfo&isur_cds=" + isur_cds + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    mdsUndesign.DataID = encodeURI(url);
    mdsUndesign.reset();
};
scwin.getCheckedIsurCd = function() {
    var tmpInt = 1;
    scwin.gubun = 2;
    var isur_cds = "";
    for (var i = 1; i <= dts_nonByCorpList.getTotalRow(); i++) {
        if (dts_nonByCorpList.getCellData(i, "CHK_FLAG") == 1) {
            dts_Save.insertRow();
            dts_Save.setCellData(tmpInt, "ISUR_CD", dts_nonByCorpList.getCellData(i, "ISUR_CD"));
            dts_Save.setCellData(tmpInt, "AF_USR_ID", dts_byCorpEmpList.getCellData(cmb_byCorpEmpList.getSelectedIndex() + 1, "USR_ID"));
            dts_Save.setCellData(tmpInt, "AF_DEP_CD", dts_byCorpEmpList.getCellData(cmb_byCorpEmpList.getSelectedIndex() + 1, "DEP_CD"));
            isur_cds = isur_cds + dts_nonByCorpList.getCellData(i, "ISUR_CD") + ",";
            tmpInt++;
        }
    }
    return isur_cds;
};


