        trs_Save.Action = "/PFInfo.do?method=saveCorpIsu&inputMessageId=search_corp_isu" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
        trs_Save.Post();
    }
};
scwin.fn_chk_cancle = function(sval) {
    //데이터셋 체크박스 초기화
    for (var i = 1; i <= sval.getTotalRow(); i++) {
