};
scwin.fn_change_stat = function(sval) {
    var t_msg = "";
    var tmpInt = 1;
    scwin.gubun = 3;
    if (scwin.chkDupDisign(dts_chgByCorpList)) {
        $c.win.alert("한 회사에 대해 같은날 두번 이상 담당자 변경을 할 수 없습니다.\n관리자에게 문의 하십시오.");
        return;
    }
    if (sval == "all") {
        t_msg = "일괄해제";
        for (var i = 1; i <= dts_chgByCorpList.getTotalRow(); i++) {
            dts_Save.insertRow();
            dts_Save.setCellData(tmpInt, "ISUR_CD", dts_chgByCorpList.getCellData(i, "ISUR_CD"));
            dts_Save.setCellData(tmpInt, "PRE_USR_ID", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "USR_ID"));
            dts_Save.setCellData(tmpInt, "PRE_DEP_CD", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "DEP_CD"));
            tmpInt++;
        }
    } else {
        t_msg = "선택해제";
        if (!scwin.fn_cntDatasetRowCheck(dts_chgByCorpList)) {
            $c.win.alert("변경하실 종목 목록중 체크사항이 없습니다.");
            return;
        } else {
            for (var i = 1; i <= dts_chgByCorpList.getTotalRow(); i++) {
                if (dts_chgByCorpList.getCellData(i, "CHK_FLAG") == 1) {
                    dts_Save.insertRow();
                    dts_Save.setCellData(tmpInt, "ISUR_CD", dts_chgByCorpList.getCellData(i, "ISUR_CD"));
                    dts_Save.setCellData(tmpInt, "PRE_USR_ID", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "USR_ID"));
                    dts_Save.setCellData(tmpInt, "PRE_DEP_CD", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "DEP_CD"));
                    tmpInt++;
                }
            }
        }
    }
    var msg = $c.stf.getMessageParam("MSG-A006", t_msg);
    var res = window.confirm(msg);
    if (res) {
        trs_Save.Action = "/PFInfo.do?method=saveCorpIsu&inputMessageId=search_corp_isu";
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
        trs_Save.Post();
    }
};
scwin.fn_change_stock = function() {
    //전체목록에서 현 담당자로 종목변경
    var tmpInt = 1;
    scwin.gubun = 3;
    //전체목록에서 현 담당자로 종목변경
    if (scwin.chkDupDisign(dts_allByCorpList)) {
        $c.win.alert("한 회사에 대해 같은날 두번 이상 담당자 변경을 할 수 없습니다.\n관리자에게 문의 하십시오.");
        return;
    }
    if (!scwin.fn_cntDatasetRowCheck(dts_allByCorpList)) {
        $c.win.alert("변경하실 종목 목록중 체크사항이 없습니다.");
    } else {
        for (var i = 1; i <= dts_allByCorpList.getTotalRow(); i++) {
            if (dts_allByCorpList.getCellData(i, "CHK_FLAG") == 1) {
                dts_Save.insertRow();
                dts_Save.setCellData(tmpInt, "ISUR_CD", dts_allByCorpList.getCellData(i, "ISUR_CD"));
                dts_Save.setCellData(tmpInt, "PRE_USR_ID", dts_allByCorpList.getCellData(i, "INTEG_USR_ID"));
                dts_Save.setCellData(tmpInt, "PRE_DEP_CD", dts_allByCorpList.getCellData(i, "DEP_CD"));
                dts_Save.setCellData(tmpInt, "AF_USR_ID", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "USR_ID"));
                dts_Save.setCellData(tmpInt, "AF_DEP_CD", dts_chgEmpList.getCellData(cmb_chgEmpList.getSelectedIndex() + 1, "DEP_CD"));
                tmpInt++;
            }
        }
        var msg = $c.stf.getMessageParam("MSG-A006", "담당변경");
        var res = window.confirm(msg);
        if (res) {
            trs_Save.Action = "/PFInfo.do?method=saveCorpIsu&inputMessageId=search_corp_isu";
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
            trs_Save.Post();
        }
    }
};
